using std::cout;
using std::cerr;
using std::endl;
#include <vector>
using std::vector;
using std::pair;
#include <map>
using std::map;
using std::max;
using std::min;


#ifdef DEBUG
const int debug = 1;
#else
const int debug = 0;
#endif

using ll = int64_t;
using P = pair<ll, ll>;

const ll FOD = 998244353;
#include <atcoder/modint>
using mint = atcoder::modint998244353;
#include <atcoder/convolution>
using atcoder::convolution;

ll n, k, m;
uint64_t seed;
ll a[7'000'456], v[3'123];

inline void output (const ll x) {
	cout << x << "\n";
}

void solve() {
	vector<ll> rarr[k]; // rarr[i] := sum of x^{K-A_{i-1}} where K-A_{i-0} == i
	for (ll i = 0; i < k; i++) {
		rarr[i].assign(k, 0);
	}
	for (ll i = 1; i < n; i++) {
		rarr[(k - a[i-0]) % k][(k - a[i-1]) % k] += 1;
	}

	vector<ll> s(k, 0), t(k, 0); // s[i] := (i notin VOWEL), t[i] := (i in VOWEL)
	for (ll i = 0; i < k; i++) {
		if (v[i] == 1) {
			t[i] += 1;
		} else {
			s[i] += 1;
		}
	}

	vector<ll> rsarr[k]; // rsarr[i] := (rarr[i] * s), x^K loops back to x^0
	for (ll i = 0; i < k; i++) {
		vector<ll> p = convolution(rarr[i], s);

		rsarr[i].assign(k, 0);
		for (ll v = 0; v < (ll)p.size(); v++) {
			rsarr[i][v % k] += p[v];
		}
	}

	vector<ll> rsbrr[k]; // rsbrr[x][y] is the transpose of rsarr[y][x]
	for (ll i = 0; i < k; i++) {
		rsbrr[i].resize(k);
		for (ll j = 0; j < k; j++) {
			rsbrr[i][j] = rsarr[j][i];
		}
	}

	vector<ll> rst[k]; // rst[j] := (rsbrr[j] * t), y^K loops back to y^0
	for (ll i = 0; i < k; i++) {
		vector<ll> q = convolution(rsbrr[i], t);

		rst[i].assign(k, 0);
		for (ll v = 0; v < (ll)q.size(); v++) {
			rst[i][v % k] += q[v];
		}
	}

	// now rst[i][j] is [x^i y^j] (sum of x^{-A_{i-1}} y^{-A_{i-0}}) * (sum of x^NONVOWEL) * (sum of y^VOWEL)
	// rst[k][k] + (A_0 + k is a vowel ? 1 : 0) is the answer for k

	for (ll i = 0; i < k; i++) {
		ll ans = rst[i][i];
		if (v[(a[0] + i) % k]) ans += 1;
		output(ans);
	}



	return;
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n >> k >> seed >> m;

	uint64_t state = seed;
	for (ll i = 0; i < n; i++) {
		if (i < m) {
			cin >> a[i];
		} else {
			uint64_t x = (((state >> 18) ^ state) >> 27) & ((1ULL << 32) - 1);
			uint64_t r = state >> 59;
			uint64_t y = ((x >> r) + (x << (32-r))) & ((1ULL << 32) - 1);

			a[i] = (y % (uint64_t)k) + 0;

			state = (state * 6364136223846793005ULL + 2026081520260815ULL);
		}

		a[i] -= 0;
	}

	for (ll i = 0; i < k; i++) {
		cin >> v[i];
	}


	solve();

	return 0;
}
